package dev.zomboid.hordes;
import java.util.*;import java.nio.file.*;
public final class CorpseBalance35 {
 static final Map<Object,List<Object>>GEAR=Collections.synchronizedMap(new WeakHashMap<>()),DROPS=Collections.synchronizedMap(new WeakHashMap<>());
 static final double RATE=100./13;static final Map<String,Double>DEFAULTS=Map.of("loot_arma_rara",RATE,"loot_armadura_rara",RATE,"loot_municion_rara",35.,"ropa_militar",RATE,"armas_cargadas",0.);
 static Object c(Object o,String n,Object...a){return ZoneReflection.call(o,n,a);}static boolean yes(Object o){return Boolean.TRUE.equals(o);}static double roll(Object level){return ((Number)c(ZoneReflection.get(level,"random"),"nextDouble")).doubleValue();}static int pick(Object level,int n){return ((Number)c(ZoneReflection.get(level,"random"),"nextInt",n)).intValue();}
 static boolean empty(Object s){return s==null||yes(c(s,"isEmpty"));}static Object copy(Object s){return c(s,"copy");}static int count(Object s){return ((Number)c(s,"getCount")).intValue();}static boolean same(Object a,Object b){return yes(c(ZoneReflection.type("net.minecraft.world.item.ItemStack"),"isSameItemSameComponents",a,b));}
 static List<Object> equipment(Object e){List<Object>r=new ArrayList<>();for(Object s:(Iterable<?>)c(e,"getArmorSlots"))if(!empty(s))r.add(copy(s));for(String name:new String[]{"getMainHandItem","getOffhandItem"}){Object s=c(e,name);if(!empty(s))r.add(copy(s));}return r;}
 public static void capture(Object entity){try{GEAR.put(entity,equipment(entity));}catch(RuntimeException e){warn("equipo antes de morir",e);}}
 public static void captureDrops(Object entity,Collection<?>drops){List<Object>r=new ArrayList<>();for(Object drop:drops){Object s=c(drop,"getItem");if(!empty(s))r.add(copy(s));}DROPS.put(entity,r);}
 // Merge two views of the SAME owned items using counts, not a set: two identical boots remain two boots.
 static List<Object>merge(List<?>a,List<?>b){List<Object>out=new ArrayList<>();List<Object>remaining=new ArrayList<>();for(Object x:a){out.add(copy(x));remaining.add(copy(x));}for(Object x:b){Object rest=copy(x);for(Object s:remaining)if(!empty(s)&&same(s,rest)){int used=Math.min(count(s),count(rest));c(s,"shrink",used);c(rest,"shrink",used);}if(!empty(rest))out.add(rest);}return out;}
 static List<Object>take(Map<Object,List<Object>>m,Object e){List<Object>r=m.remove(e);return r==null?List.of():r;}
 static String entityId(Object e){return String.valueOf(c(c(e,"getType"),"getDescriptionId")).toLowerCase(Locale.ROOT);}static boolean npc(Object e){String id=entityId(e);return id.contains("tacznpcs")||id.contains("bandit");}
 static boolean military(Object e,List<?>gear){Object tag=c(e,"getPersistentData");StringBuilder hints=new StringBuilder(entityId(e));Object name=c(e,"getCustomName");if(name!=null)hints.append(' ').append(c(name,"getString"));for(String k:new String[]{"TacZNpcJob","profession","Profession","skin","Skin","outfit","Outfit"})hints.append(' ').append(c(tag,"getString",k));
  String text=hints.toString().toLowerCase(Locale.ROOT);if(text.contains("military")||text.contains("militar")||text.contains("soldier")||text.contains("soldado")||text.contains("juggernaut")||text.contains("army"))return true;
  for(Object s:gear){String id=LootNerf.id(s);if(id.startsWith("fracturepoint:")&&(LootNerf.kind(s)==LootNerf.ARMOR||id.contains("jugger")))return true;}
  for(String k:new String[]{"military","Military","zh_military","TacZNpcMilitary"})if(yes(c(tag,"getBoolean",k)))return true;return false;
 }
 static boolean mutant(Object corpse,Object entity){try{return yes(ZoneReflection.get(corpse,"mutant"));}catch(RuntimeException ex){return entityId(entity).contains("mutant")||entityId(entity).contains("mutantszombies");}}
 static List<Object>items(Object inv){List<Object>r=new ArrayList<>();for(int i=0;i<((Number)c(inv,"getContainerSize")).intValue();i++){Object s=c(inv,"getItem",i);if(!empty(s))r.add(copy(s));}return r;}
 static void write(Object inv,List<?>items,Object level){int n=((Number)c(inv,"getContainerSize")).intValue();if(items.size()>n){c(inv,"ensure",items.size());n=((Number)c(inv,"getContainerSize")).intValue();}List<Integer>slots=new ArrayList<>();for(int i=0;i<n;i++)slots.add(i);for(int i=n-1;i>0;i--){int j=pick(level,i+1);Collections.swap(slots,i,j);}c(inv,"clearContent");for(int i=0;i<items.size();i++)c(inv,"setItem",slots.get(i),items.get(i));c(inv,"setChanged");}
 static void warn(String what,Exception e){System.getLogger("CorpseBalance35").log(System.Logger.Level.ERROR,"No se pudo ajustar "+what,e);}
 public static void defaults(Map<String,Double>d,Map<String,Double>values){d.putAll(DEFAULTS);values.putAll(DEFAULTS);}public static void prepare(Map<String,Double>d){d.putAll(DEFAULTS);}
 static final Set<Path>attempted=new HashSet<>();public static void migrate(){Path file=(Path)ZoneReflection.get(WorldTuning.class,"file");if(file==null)return;Path marker=file.resolveSibling("zomboid-corpse-balance35.marker");if(Files.exists(marker)||!attempted.add(file))return;try{Map<String,Double>d=new HashMap<>(WorldTuning.snapshot());prepare(d);WorldTuning.batch(d,WorldTuning.revision());Files.writeString(marker,"Weapon and military loot 1/13; matching ammunition 35%. Other settings preserved.\n",StandardOpenOption.CREATE_NEW);}catch(Exception e){warn("probabilidades iniciales",e);}}
 public static boolean chance(Object level,String key){return roll(level)<Math.max(0,Math.min(100,WorldTuning.get(key)))/100;}
 static List<Object>registryPool(boolean armor){List<Object>pool=new ArrayList<>();Object reg=ZoneReflection.get(ZoneReflection.type("net.minecraft.core.registries.BuiltInRegistries"),"ITEM");for(Object item:(Iterable<?>)reg){String id=String.valueOf(c(reg,"getKey",item));if(armor&&(!id.startsWith("fracturepoint:")||!LootNerf.family(item,"ArmorItem")||id.contains("nvg")||id.contains("backpack")))continue;Object s=CorpseProfessions.stack(id);if(s==null)continue;if(armor||LootNerf.kind(s)==LootNerf.WEAPON&&!id.contains("kinetic_gun"))pool.add(s);}return pool;}
 static Object gun(Object level,int q){try{Object profile=c(ZoneReflection.type("dev.zomboid.remains.WeaponLoot"),"choose",q,ZoneReflection.get(level,"random"));if(profile!=null){Object s=c(ZoneReflection.type("dev.zomboid.remains.GunAccess"),"create",profile,0);if(!empty(s)){c(ZoneReflection.type("dev.zomboid.remains.GunAccess"),"load",s,0);return s;}}}catch(RuntimeException ex){warn("catalogo de armas",ex);}return null;}
 static Object weapon(Object level,int q,List<?>candidates){boolean firearm=roll(level)<.65;Object gun=firearm?gun(level,q):null;if(gun!=null)return gun;List<Object>melee=registryPool(false);if(!melee.isEmpty())return copy(melee.get(pick(level,melee.size())));if(!firearm){gun=gun(level,q);if(gun!=null)return gun;}for(Object s:candidates)if(LootNerf.kind(s)==LootNerf.WEAPON){Object out=copy(s);c(out,"setCount",1);LootNerf.unloadGenerated(out,0);return out;}return null;}
 static Object ammo(Object weapon,Object level,int q){try{Object profile=c(ZoneReflection.type("dev.zomboid.remains.GunAccess"),"describe",weapon);if(profile==null)return null;return c(ZoneReflection.type("dev.zomboid.remains.WeaponLoot"),"ammo",c(profile,"ammo"),2+pick(level,3+Math.min(5,q)));}catch(RuntimeException ex){warn("municion compatible",ex);return null;}}
 static void generated(List<Object>out,List<?>candidates,Object level,int q){if(chance(level,"loot_arma_rara")){Object s=weapon(level,q,candidates);if(!empty(s)){out.add(s);if(chance(level,"loot_municion_rara")){Object ammo=ammo(s,level,q);if(!empty(ammo))out.add(ammo);}}}if(chance(level,"loot_armadura_rara")){List<Object>armor=registryPool(true);if(!armor.isEmpty())out.add(copy(armor.get(pick(level,armor.size()))));}}
 static Object bandage(){Object s=CorpseProfessions.stack("firstaid:bandage@2");if(s!=null){Object key=ZoneReflection.get(ZoneReflection.type("net.minecraft.core.component.DataComponents"),"CUSTOM_NAME");c(s,"set",key,c(ZoneReflection.type("net.minecraft.network.chat.Component"),"translatable","item.zomboid_hordes.military_bandage",new Object[0]));}return s;}
 static List<Object>mutantItems(Object e,Object level,int q){String id=entityId(e);List<String>pool=new ArrayList<>(List.of("rotten_flesh","bone"));if(id.contains("blister")||id.contains("spitter"))pool.addAll(List.of("slime_ball","spider_eye"));if(id.contains("crawler"))pool.add("string");List<Object>out=new ArrayList<>();for(int i=0;i<2+Math.min(2,q/2);i++){Object s=CorpseProfessions.stack(pool.remove(pick(level,pool.size()))+"@"+(1+pick(level,3)));if(!empty(s))out.add(s);if(pool.isEmpty())break;}return out;}
 public static void scatter(Object corpse,Object level){Object inv=ZoneReflection.get(corpse,"inventory");write(inv,items(inv),level);}
 public static void body(Object corpse,Object level,Object event){Object inv=ZoneReflection.get(corpse,"inventory");List<Object>original=items(inv);try{Object entity=c(event,"getEntity");List<Object>owned=merge(take(GEAR,entity),equipment(entity));owned=merge(owned,take(DROPS,entity));boolean isNpc=npc(entity),isMilitary=military(entity,owned),isMutant=mutant(corpse,entity);int q=LootNerf.tier(((Number)ZoneReflection.get(corpse,"quality")).intValue());List<Object>out;
   LootProfiles.markConverted(event);
   if(isNpc){out=merge(original,owned);if(isMilitary){Object b=bandage();if(!empty(b))out.add(b);}write(inv,out,level);return;}
   if(isMutant){out=mutantItems(entity,level,q);out.addAll(owned);if(isMilitary){Object b=bandage();if(!empty(b))out.add(b);}write(inv,out,level);return;}
   c(ZoneReflection.type("dev.zomboid.remains.ProfileCompat"),"corpse",corpse,level,event);List<Object>candidates=items(inv);
   if(!WorldTuning.flag("loot_balance_todos")&&!isMilitary){out=merge(candidates,owned);write(inv,out,level);return;}
   List<Object>supplies=new ArrayList<>();List<Object>protectedRemaining=new ArrayList<>();for(Object s:owned)protectedRemaining.add(copy(s));for(Object s:candidates){Object rest=copy(s);for(Object own:protectedRemaining)if(!empty(own)&&same(own,rest)){int used=Math.min(count(own),count(rest));c(own,"shrink",used);c(rest,"shrink",used);}if(empty(rest))continue;int kind=LootNerf.kind(rest);if(kind!=LootNerf.WEAPON&&kind!=LootNerf.ARMOR&&kind!=LootNerf.AMMO)supplies.add(rest);}
   out=LootNerf.filter(supplies,level,q,List.of());if(!isMilitary)generated(out,candidates,level,q);else{Object b=bandage();if(!empty(b))out.add(b);} // No equipment roll can delete actual military gear.
   // One generated tool, preserving every owned item (even a real tool).
   Object preferredTool=null;for(Object s:out)if(LootNerf.kind(s)==LootNerf.WEAPON&&CorpseProfessions.tool(s))preferredTool=s;boolean tool=preferredTool!=null;for(Iterator<Object>it=out.iterator();it.hasNext();){Object s=it.next();if(CorpseProfessions.tool(s)){if(s==preferredTool)c(s,"setCount",1);else if(tool)it.remove();else{tool=true;c(s,"setCount",1);}}}
   out.addAll(owned);write(inv,out,level);
  }catch(RuntimeException ex){warn("cadaver; inventario original restaurado",ex);c(inv,"clearContent");for(int i=0;i<original.size();i++)c(inv,"setItem",i,original.get(i));}
 }
}
